CREATE UNIQUE INDEX "gym_members_business_id_member_no_key" ON "gym_members"("business_id","member_no"); CREATE INDEX "gym_members_business_id_status_idx" ON "gym_members"("business_id","status"); ALTER TABLE "gym_members" ADD CONSTRAINT "gym_members_business_id_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE CASCADE;
