CREATE INDEX "gym_memberships_business_id_status_end_date_idx" ON "gym_memberships"("business_id","status","end_date"); ALTER TABLE "gym_memberships" ADD CONSTRAINT "gym_memberships_business_id_fkey" FOREIGN KEY ("business_id") REFERENCES "businesses"("id") ON DELETE CASCADE; ALTER TABLE "gym_memberships" ADD CONSTRAINT "gym_memberships_member_id_fkey" FOREIGN KEY ("member_id") REFERENCES "gym_members"("id") ON DELETE RESTRICT; ALTER TABLE "gym_memberships" ADD CONSTRAINT "gym_memberships_plan_id_fkey" FOREIGN KEY ("plan_id") REFERENCES "gym_membership_plans"("id") ON DELETE RESTRICT;
